inline std::string primary_media_path(const doc::Document& doc) {
    const doc::Asset* a = doc.primary_asset();
    return a ? a->path : std::string();
}

// This is environment setup, not an undoable edit.
// Never rewrite the path of an existing asset: it changes media under
// every placement.
inline void bind_primary_media(doc::Document& doc, const std::string& path) {
    uint64_t asset_id = 0;
    for (const doc::Asset& a : doc.assets)
        if (a.path == path) asset_id = a.id;
    if (!asset_id) {
        doc::Asset a;
        a.id = doc.next_effect_id++;
        a.path = path;
        a.name = path_to_u8(u8_to_path(path).filename());
        asset_id = a.id;
        doc.assets.push_back(std::move(a));
    }
    for (doc::Look& look : doc.looks)
        for (doc::Layer& l : look.layers)
            if (doc::layer_is_media(l) && !l.asset) l.asset = asset_id;
}

struct ExportJob {
    std::thread thread;
    media::ExportProgress progress;
    media::ExportResult result;
    std::atomic<bool> done{false};
    std::filesystem::path out_path;

    ~ExportJob() {
        progress.cancel = true;
        if (thread.joinable()) thread.join();
    }
};

inline std::vector<gfx::Engine::LayerSourceFrame> to_layer_sources(
    const std::vector<media::SourceFrame>& frames) {
    std::vector<gfx::Engine::LayerSourceFrame> out;
    out.reserve(frames.size());
    for (const media::SourceFrame& sf : frames) {
        if (!sf.frame) continue;
        const codec::FrameView view = sf.frame->view();
        gfx::Engine::LayerSourceFrame lf;
        lf.key = sf.key;
        lf.content_stamp = sf.frame->stamp;
        lf.planes.nv12 = sf.frame->nv12;
        lf.planes.y = view.y.data;
        lf.planes.y_stride = view.y.stride;
        lf.planes.u = view.u.data;
        lf.planes.u_stride = view.u.stride;
        lf.planes.v = view.v.data;
        lf.planes.v_stride = view.v.stride;
        lf.planes.width = view.width;
        lf.planes.height = view.height;
        out.push_back(lf);
    }
    return out;
}

// Preview and export share this converter to keep frames bit-identical.
inline mod::SourceFrameView source_view(const gfx::SourcePlanes& p) {
    mod::SourceFrameView sfv;
    sfv.y = p.y;
    sfv.y_stride = p.y_stride;
    sfv.u = p.u;
    sfv.u_stride = p.u_stride;
    sfv.v = p.v;
    sfv.v_stride = p.v_stride;
    sfv.width = static_cast<int>(p.width);
    sfv.height = static_cast<int>(p.height);
    sfv.nv12 = p.nv12;
    return sfv;
}

inline constexpr double kEmptyTimelineSeconds = 10.0;

inline uint32_t timeline_buffer_frames(double fps) {
    return static_cast<uint32_t>(std::max(60.0, (fps > 0.0 ? fps : 30.0) * 2.0));
}

// This must agree with the doc-side fps that the flatten conforms with.
inline double project_fps(const doc::Document& doc,
                          const std::vector<media::AssetBundle>& bundles) {
    if (doc.fps > 0.0) return doc.fps;
    for (const doc::Asset& a : doc.assets)
        if (a.fps > 0.0) return a.fps;
    for (const media::AssetBundle& b : bundles)
        if (b.fps > 0.0) return b.fps;
    return 30.0;
}

// Use the bundle timescale: a double cannot hold 30000/1001 exactly.
inline void frame_rate_ratio(double fps,
                             const std::vector<media::AssetBundle>& bundles,
                             uint32_t* num, uint32_t* den) {
    for (const media::AssetBundle& b : bundles)
        if (b.frame_duration && b.timescale && std::abs(b.fps - fps) < 1e-6) {
            *num = b.timescale;
            *den = b.frame_duration;
            return;
        }
    *num = static_cast<uint32_t>(fps * 1000.0 + 0.5);
    *den = 1000;
}

using PcmCache =
    std::unordered_map<uint64_t, std::shared_ptr<const media::PcmBuffer>>;

inline bool to_mix_op(const doc::AudioOp& op, media::MixOp* m) {
    switch (op.type) {
        case doc::EffectType::AudioGain:
            m->kind = media::MixOpKind::Gain;
            break;
        case doc::EffectType::AudioBitcrush:
            m->kind = media::MixOpKind::Bitcrush;
            break;
        case doc::EffectType::AudioDownsample:
            m->kind = media::MixOpKind::Downsample;
            break;
        case doc::EffectType::AudioDistortion:
            m->kind = media::MixOpKind::Distortion;
            break;
        case doc::EffectType::AudioDelay:
            m->kind = media::MixOpKind::Delay;
            break;
        case doc::EffectType::AudioFilter:
            m->kind = media::MixOpKind::Filter;
            break;
        default:
            return false;
    }
    for (int i = 0; i < 4; ++i) m->p[i] = op.params[i];
    m->wet = op.wet;
    return true;
}

// doc_nodes maps each doc node id to its program node index.
inline media::MixState build_mix(const doc::Document& doc, uint64_t look_id,
                                 const PcmCache& pcm, double fps,
                                 uint32_t rate, uint32_t channels,
                                 std::unordered_map<uint64_t, int>*
                                     doc_nodes = nullptr) {
    media::MixState mix;
    mix.fps = fps > 0.0 ? fps : 30.0;
    mix.rate = rate;
    mix.channels = channels;
    // The scoped entity length limits an unbounded placement.
    uint32_t span = 0;
    if (const doc::Look* l = doc.find_look(look_id))
        span = doc::look_duration(doc, *l);
    else if (const doc::Sequence* s = doc.find_sequence(look_id))
        span = doc::sequence_duration(doc, *s);
    const double horizon =
        static_cast<double>(std::max<uint32_t>(span, 1));
    const doc::AudioProgram prog = doc::flatten_audio_program(doc, look_id);
    if (prog.root < 0) return mix;
    if (doc_nodes)
        for (size_t i = 0; i < prog.nodes.size(); ++i)
            if (prog.nodes[i].doc_id)
                (*doc_nodes)[prog.nodes[i].doc_id] =
                    static_cast<int>(i);
    mix.nodes.reserve(prog.nodes.size());
    for (const doc::AudioNode& n : prog.nodes) {
        media::MixNode m;
        m.a = n.a;
        // The mix maps in seconds. Convert the frame shift through the rate.
        m.b = n.b + (n.asset && n.rate > 0.0
                         ? static_cast<double>(n.shift) / n.rate
                         : 0.0);
        m.local_fps = n.local_fps;
        m.windowed = n.windowed;
        m.w0 = n.w0;
        m.w1 = n.w1 >= doc::kUnbounded ? media::kMixUnbounded : n.w1;
        m.gain = n.gain;
        m.inputs = n.inputs;
        if (n.asset) {
            // A missing sidecar is a silent leaf, not an error.
            const auto it = pcm.find(n.asset);
            if (it != pcm.end()) m.pcm = it->second;
        }
        if (n.has_op) m.has_op = to_mix_op(n.op, &m.op);
        mix.nodes.push_back(std::move(m));
    }
    mix.root = prog.root;
    // Wrap an unwindowed root in a horizon hop: cuts sit above the DSP.
    media::MixNode& root = mix.nodes[static_cast<size_t>(mix.root)];
    if (root.windowed) {
        root.w1 = std::min(root.w1, horizon);
    } else {
        media::MixNode hop;
        hop.windowed = true;
        hop.w1 = horizon;
        hop.inputs.push_back(mix.root);
        mix.nodes.push_back(std::move(hop));
        mix.root = static_cast<int>(mix.nodes.size()) - 1;
    }
    media::prepare_mix(mix);
    return mix;
}

// The worker thread owns the preview Engine.
// Do not rewrite a published image until the UI frame that read it retires.
struct RenderWorker {
    struct Job {
        // Immutable snapshot. The UI builds it outside the lock.
        std::shared_ptr<const doc::Document> doc;
        uint64_t doc_revision = ~0ull;
        // Skip render-cache hashing and readback during a drag.
        bool interactive = false;
        // During a drag the worker applies this overlay to its own copy.
        uint64_t gesture_revision = 0;
        uint64_t gesture_seq = 0;
        doc::Placement gesture_place{};
        mod::AnalysisCurves analysis;
        bool has_analysis = false;
        uint64_t analysis_stamp = ~0ull;
        // Immutable snapshot. Republish by pointer, do not mutate in place.
        std::shared_ptr<const mod::NodeAudioMap> node_audio;
        std::shared_ptr<const mod::NodeCameraMap> node_camera;
        std::shared_ptr<const gfx::Engine::PinPlaneMap> pin_planes;
        // The decode pool resolves placements through this, not the document.
        std::vector<media::AssetBundle> bundles;
        uint64_t bundle_stamp = ~0ull;
        uint64_t look_id = 0;
        // 0 = the composite. preview_node outranks preview_layer.
        uint64_t preview_node = 0;
        uint64_t preview_layer = 0;
        // The render measures the pre-Motion alpha bounds of this block.
        uint64_t sel_placement = 0;
        uint32_t preview_div = 1;
        uint32_t pub_w = 0, pub_h = 0;
        bool live_mode = false;
        double app_seconds = 0.0;
        double env_key_time = -1.0;
        bool want_source = false;
        bool proxy_active = false;        // cache key ingredient
        // While set, the pool can serve nearby frames and stores no cache.
        bool scrubbing = false;
        // Gray ramp bytes, or RGBA when glyph_is_color. Alpha gives coverage.
        std::vector<uint8_t> glyph_data;
        uint32_t glyph_w = 0, glyph_h = 0, glyph_cols = 16, glyph_rows = 6;
        float glyph_tile = 8.0f;
        bool glyph_is_color = false;
        bool glyph_pending = false;
        // Mono PCM copy. Empty means silent media.
        std::vector<int16_t> scope_data;
        uint32_t scope_rate = 0;
        bool scope_pending = false;
    };

    struct View {
        gfx::GpuImage* final_img = nullptr;    // SHADER_READ_ONLY or null
        gfx::GpuImage* source_img = nullptr;
        // The cell map stays consistent with this atlas snapshot.
        gfx::GpuImage* thumb_img = nullptr;
        std::unordered_map<uint64_t, uint32_t> thumb_cells;
        // bounds are canvas fractions and apply only to bounds_placement.
        uint64_t doc_revision = 0;
        uint64_t publish_seq = 0;
        float bounds[4] = {0.0f, 0.0f, 1.0f, 1.0f};
        bool bounds_valid = false;
        uint64_t bounds_placement = 0;
    };

    RenderWorker(gfx::Device& dev, media::Player& p,
                 std::unique_ptr<gfx::Engine> eng)
        : device(dev), player(p), engine(std::move(eng)) {}
    ~RenderWorker() { stop(); }

    bool start() {
        VkCommandPoolCreateInfo pool_info{
            VK_STRUCTURE_TYPE_COMMAND_POOL_CREATE_INFO};
        pool_info.flags = VK_COMMAND_POOL_CREATE_RESET_COMMAND_BUFFER_BIT;
        pool_info.queueFamilyIndex = device.graphics_family();
        if (vkCreateCommandPool(device.device(), &pool_info, nullptr,
                                &pool_) != VK_SUCCESS)
            return false;
        VkCommandBufferAllocateInfo cb{
            VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO};
        cb.commandPool = pool_;
        cb.level = VK_COMMAND_BUFFER_LEVEL_PRIMARY;
        cb.commandBufferCount = gfx::kFramesInFlight;
        if (vkAllocateCommandBuffers(device.device(), &cb, cmd_) !=
            VK_SUCCESS)
            return false;
        VkFenceCreateInfo fence_info{VK_STRUCTURE_TYPE_FENCE_CREATE_INFO};
        for (uint32_t i = 0; i < gfx::kFramesInFlight; ++i)
            if (vkCreateFence(device.device(), &fence_info, nullptr,
                              &fence_[i]) != VK_SUCCESS)
                return false;
        // Ring: the UI slot, the in-flight submissions, and one free target.
        published_.resize(2 + gfx::kFramesInFlight);
        thread_ = std::thread([this] { run(); });
        return true;
    }

    void stop() {
        if (stopped_) return;   // the destructor re-enters after main stops it
        stopped_ = true;
        log_info("shutdown: render worker stopping");
        {
            std::lock_guard<std::mutex> lock(m_);
            quit_ = true;
            if (pool_ptr_) pool_ptr_->abort();
        }
        cv_.notify_all();
        if (thread_.joinable()) thread_.join();
        log_info("shutdown: render worker joined");
        device.wait_idle();
        log_info("shutdown: render device idle");
        published_.clear();
        graveyard_.clear();
        engine.reset();
        log_info("shutdown: render engine freed");
        for (uint32_t i = 0; i < gfx::kFramesInFlight; ++i) {
            if (fence_[i]) vkDestroyFence(device.device(), fence_[i], nullptr);
            fence_[i] = VK_NULL_HANDLE;
        }
        if (pool_) vkDestroyCommandPool(device.device(), pool_, nullptr);
        pool_ = VK_NULL_HANDLE;
    }

    // MezReader ownership is not thread-safe, so hold the worker idle across
    // player open and close. The counter makes this re-entrant.
    void pause() {
        std::unique_lock<std::mutex> lock(m_);
        ++pause_count_;
        cv_.wait(lock, [&] { return idle_ || quit_; });
    }
    void resume() {
        {
            std::lock_guard<std::mutex> lock(m_);
            --pause_count_;
        }
        cv_.notify_all();
    }

    void invalidate() {
        std::lock_guard<std::mutex> lock(m_);
        latest_ = -1;
        for (Published& p : published_) p.ready = false;
    }

    // Call once per UI frame. The worker keeps the image until the fence waits.
    View acquire(uint64_t ui_frame) {
        std::lock_guard<std::mutex> lock(m_);
        if (latest_ < 0 || !published_[static_cast<size_t>(latest_)].ready)
            return {};
        Published& p = published_[static_cast<size_t>(latest_)];
        p.last_ui_frame = ui_frame;
        View v;
        v.final_img = p.final_img.get();
        v.source_img = p.has_source ? p.source_img.get() : nullptr;
        v.thumb_img = p.has_thumbs ? p.thumb_img.get() : nullptr;
        if (p.has_thumbs) v.thumb_cells = p.thumb_cells;
        v.doc_revision = p.doc_revision;
        v.publish_seq = p.cycle_seq;
        for (int i = 0; i < 4; ++i) v.bounds[i] = p.bounds[i];
        v.bounds_valid = p.bounds_valid;
        v.bounds_placement = p.bounds_placement;
        return v;
    }

    void set_completed_ui_frame(uint64_t f) {
        completed_ui_frame_.store(f, std::memory_order_relaxed);
    }

    // poke forces one fresh cycle: a seek alone moves no document revision.
    uint64_t snapshot_seq() const { return cycle_seq_.load(); }
    void poke() {
        {
            std::lock_guard<std::mutex> lock(m_);
            ++job_serial_;
        }
        cv_.notify_all();
    }

    // Counts distinct timeline frames. Re-renders of one frame do not count.
    uint64_t frames_advanced() const {
        return frames_advanced_.load(std::memory_order_relaxed);
    }

    // Smoothed render-cycle wall time in ms.
    // Phase index: 0 decode wait, 1 resolve, 2 record, 3 GPU fence wait.
    double cycle_ms() const {
        return cycle_ms_x100_.load(std::memory_order_relaxed) / 100.0;
    }
    double phase_ms(int i) const {
        return phase_ms_x100_[i & 3].load(std::memory_order_relaxed) /
               100.0;
    }

    void post_glyph_atlas(std::vector<uint8_t> data, uint32_t w, uint32_t h,
                          float tile, uint32_t cols, uint32_t rows,
                          bool is_color = false) {
        {
            std::lock_guard<std::mutex> lock(m_);
            job_.glyph_data = std::move(data);
            job_.glyph_w = w;
            job_.glyph_h = h;
            job_.glyph_tile = tile;
            job_.glyph_cols = cols;
            job_.glyph_rows = rows;
            job_.glyph_is_color = is_color;
            job_.glyph_pending = true;
            ++job_serial_;
        }
        cv_.notify_all();
    }

    void post_scope_audio(std::vector<int16_t> mono, uint32_t rate) {
        {
            std::lock_guard<std::mutex> lock(m_);
            job_.scope_data = std::move(mono);
            job_.scope_rate = rate;
            job_.scope_pending = true;
            ++job_serial_;
        }
        cv_.notify_all();
    }

    gfx::Device& device;
    media::Player& player;
    std::unique_ptr<gfx::Engine> engine;

    // m_ guards the job snapshot and the publish ring.
    std::mutex m_;
    std::condition_variable cv_;
    Job job_;
    uint64_t job_serial_ = 0;

private:
    struct Published {
        std::unique_ptr<gfx::GpuImage> final_img, source_img;
        // Fixed size atlas. Do not retire it on resize.
        std::unique_ptr<gfx::GpuImage> thumb_img;
        std::unordered_map<uint64_t, uint32_t> thumb_cells;
        uint32_t w = 0, h = 0;
        bool has_source = false;
        bool has_thumbs = false;   // atlas copy recorded at least once
        bool ready = false;
        uint64_t last_ui_frame = 0;
        uint64_t doc_revision = 0;
        uint64_t cycle_seq = 0;
        float bounds[4] = {0.0f, 0.0f, 1.0f, 1.0f};
        bool bounds_valid = false;
        uint64_t bounds_placement = 0;
    };

    void run();
    bool ensure_published(Published& p, uint32_t w, uint32_t h,
                          bool want_source, uint64_t completed);

    bool quit_ = false;
    bool stopped_ = false;   // stop() ran (the destructor re-enters)
    bool idle_ = false;
    int pause_count_ = 0;
    // Published under m_ so stop() can abort a roll. Null outside run().
    media::DecodePool* pool_ptr_ = nullptr;
    std::vector<Published> published_;
    int latest_ = -1;
    uint64_t published_seq_high_ = 0;
    std::atomic<uint64_t> completed_ui_frame_{0};
    std::atomic<uint64_t> frames_advanced_{0};
    std::atomic<uint32_t> cycle_ms_x100_{0};
    std::atomic<uint32_t> phase_ms_x100_[4] = {};
    // Worker thread only. perf_trace.txt beside the exe enables the csv.
    struct Perf {
        std::vector<float> rt, ph[4];
        std::chrono::steady_clock::time_point window_start{};
        bool started = false;
        FILE* trace = nullptr;
        bool trace_checked = false;
        uint64_t cycle_no = 0;
    };
    Perf perf_;
    void perf_record(double rt, const double phase[4]);
    // Old-size images wait here until the UI frames that read them retire.
    std::vector<std::pair<uint64_t, std::unique_ptr<gfx::GpuImage>>>
        graveyard_;

    std::thread thread_;
    VkCommandPool pool_ = VK_NULL_HANDLE;
    // Wait the fence of the slot you reuse, not the slot you just submitted.
    VkCommandBuffer cmd_[gfx::kFramesInFlight] = {};
    VkFence fence_[gfx::kFramesInFlight] = {};
    struct InFlight {
        bool pending = false;
        bool published_ok = false;
        int target = -1;
        uint64_t doc_revision = 0;
        uint64_t cycle_seq = 0;
        uint64_t sel_placement = 0;
        bool measured = false;
    };
    InFlight inflight_[gfx::kFramesInFlight];
    // Monotonic. A publish stamped N rendered the inputs read at cycle N.
    std::atomic<uint64_t> cycle_seq_{0};
};

bool RenderWorker::ensure_published(Published& p, uint32_t w, uint32_t h,
                                    bool want_source, uint64_t completed) {
    auto retire = [&](std::unique_ptr<gfx::GpuImage>& img) {
        if (img) graveyard_.emplace_back(p.last_ui_frame, std::move(img));
    };
    const VkImageUsageFlags usage =
        VK_IMAGE_USAGE_SAMPLED_BIT | VK_IMAGE_USAGE_TRANSFER_DST_BIT;
    if (p.w != w || p.h != h) {
        retire(p.final_img);
        retire(p.source_img);
        p.w = 0;
        p.h = 0;
    }
    if (!p.final_img) {
        p.final_img = gfx::GpuImage::create(
            device, VK_FORMAT_R16G16B16A16_SFLOAT, w, h, usage);
        if (!p.final_img) return false;
    }
    if (want_source && !p.source_img) {
        p.source_img = gfx::GpuImage::create(
            device, VK_FORMAT_R16G16B16A16_SFLOAT, w, h, usage);
        if (!p.source_img) return false;
    }
    if (!p.thumb_img) {
        p.thumb_img = gfx::GpuImage::create(
            device, VK_FORMAT_R16G16B16A16_SFLOAT,
            gfx::Engine::kThumbCellW * gfx::Engine::kThumbGridCols,
            gfx::Engine::kThumbCellH * gfx::Engine::kThumbGridRows, usage);
        if (!p.thumb_img) return false;
    }
    p.w = w;
    p.h = h;
    graveyard_.erase(
        std::remove_if(graveyard_.begin(), graveyard_.end(),
                       [&](const auto& g) { return g.first <= completed; }),
        graveyard_.end());
    return true;
}

void RenderWorker::perf_record(double rt, const double phase[4]) {
    Perf& p = perf_;
    const auto now = std::chrono::steady_clock::now();
    if (!p.started) {
        p.started = true;
        p.window_start = now;
    }
    if (!p.trace_checked) {
        p.trace_checked = true;
        std::error_code ec;
        if (std::filesystem::exists(executable_dir() / "perf_trace.txt",
                                    ec)) {
            p.trace = _wfopen(
                (executable_dir() / "looks_perf.csv").c_str(), L"wb");
            if (p.trace)
                std::fprintf(p.trace, "cycle,rt_ms,d_ms,r_ms,c_ms,g_ms\n");
        }
    }
    p.rt.push_back(static_cast<float>(rt));
    for (int i = 0; i < 4; ++i)
        p.ph[i].push_back(static_cast<float>(phase[i]));
    if (p.trace) {
        std::fprintf(p.trace, "%llu,%.2f,%.2f,%.2f,%.2f,%.2f\n",
                     static_cast<unsigned long long>(p.cycle_no), rt,
                     phase[0], phase[1], phase[2], phase[3]);
        std::fflush(p.trace);
    }
    ++p.cycle_no;
    const double window_s =
        std::chrono::duration<double>(now - p.window_start).count();
    if (window_s < 5.0) return;
    auto stat = [](std::vector<float>& v, double* avg, double* p95,
                   double* mx) {
        double sum = 0.0;
        for (const float x : v) sum += x;
        *avg = v.empty() ? 0.0 : sum / static_cast<double>(v.size());
        std::sort(v.begin(), v.end());
        *p95 = v.empty() ? 0.0 : v[v.size() * 95 / 100];
        *mx = v.empty() ? 0.0 : v.back();
    };
    double avg, p95, mx;
    stat(p.rt, &avg, &p95, &mx);
    char line[256];
    int n = std::snprintf(line, sizeof(line),
                          "perf: %zu cycles / %.1fs, rt avg %.1f p95 %.1f "
                          "max %.1f",
                          p.rt.size(), window_s, avg, p95, mx);
    static const char* names[4] = {"d", "r", "c", "g"};
    for (int i = 0; i < 4 && n > 0; ++i) {
        stat(p.ph[i], &avg, &p95, &mx);
        n += std::snprintf(line + n, sizeof(line) - static_cast<size_t>(n),
                           " | %s %.1f/%.1f/%.1f", names[i], avg, p95, mx);
    }
    log_info("%s", line);
    p.rt.clear();
    for (auto& v : p.ph) v.clear();
    p.window_start = now;
}

void RenderWorker::run() {
    // These hold FILE handles and are single-thread objects. Keep them local.
    media::DecodePool pool("preview");
    {
        std::lock_guard<std::mutex> lock(m_);
        pool_ptr_ = &pool;
    }
    struct PoolUnpublish {
        RenderWorker& w;
        ~PoolUnpublish() {
            std::lock_guard<std::mutex> lock(w.m_);
            w.pool_ptr_ = nullptr;
        }
    } pool_unpublish{*this};
    mod::TimeRemap remap;

    std::shared_ptr<const doc::Document> doc_snap;
    // doc_revision is the effective revision. It keys the pool and the
    // cache hash.
    doc::Document doc_local;
    bool local_valid = false;
    uint64_t base_revision = ~0ull;
    uint64_t doc_revision = ~0ull;
    mod::AnalysisCurves analysis;
    bool has_analysis = false;
    uint64_t analysis_stamp = ~0ull;
    std::shared_ptr<const mod::NodeAudioMap> node_audio;
    std::shared_ptr<const mod::NodeCameraMap> node_camera;
    std::shared_ptr<const gfx::Engine::PinPlaneMap> pin_planes;
    uint64_t cache_doc_hash = 0;
    bool cache_doc_history = false;
    uint64_t cache_hash_revision = ~0ull;
    std::vector<media::AssetBundle> bundles;
    uint64_t bundle_stamp = ~0ull;
    uint64_t last_serial = ~0ull;
    uint32_t last_rendered_frame = 0xFFFFFFFFu;
    bool last_had_frame = false;
    bool pending_render = false;
    uint32_t slot = 0;
    std::chrono::steady_clock::time_point cycle_start{};

    // Waits the slot fence, the only GPU sync in the cycle. Returns wait ms.
    auto complete_slot = [&](uint32_t s) -> double {
        InFlight& fl = inflight_[s];
        if (!fl.pending) return 0.0;
        const auto w0 = std::chrono::steady_clock::now();
        vkWaitForFences(device.device(), 1, &fence_[s], VK_TRUE, UINT64_MAX);
        const double wait_ms =
            std::chrono::duration<double, std::milli>(
                std::chrono::steady_clock::now() - w0)
                .count();
        fl.pending = false;
        if (fl.published_ok && fl.target >= 0) {
            Published& fpub = published_[static_cast<size_t>(fl.target)];
            float mb[4];
            const bool mb_ok =
                fl.measured && engine->read_measure_bounds(mb);
            std::lock_guard<std::mutex> lock(m_);
            fpub.doc_revision = fl.doc_revision;
            fpub.cycle_seq = fl.cycle_seq;
            fpub.bounds_valid = mb_ok;
            fpub.bounds_placement = mb_ok ? fl.sel_placement : 0;
            if (mb_ok)
                for (int i = 0; i < 4; ++i) fpub.bounds[i] = mb[i];
            fpub.ready = true;
            // Slots retire out of order. Move latest_ forward in cycle
            // order only.
            if (fl.cycle_seq >= published_seq_high_) {
                published_seq_high_ = fl.cycle_seq;
                latest_ = fl.target;
            }
        }
        return wait_ms;
    };

    for (;;) {
        uint64_t preview_node, preview_layer, look_id, sel_placement;
        uint32_t preview_div, pub_w, pub_h;
        bool live_mode, want_source, proxy_active, interactive, scrubbing;
        double app_seconds, env_key_time;
        bool doc_changed = false;
        bool fields_changed = false;
        uint64_t this_cycle = 0;
        {
            std::unique_lock<std::mutex> lock(m_);
            idle_ = true;
            cv_.notify_all();
            cv_.wait_for(lock, std::chrono::milliseconds(4), [&] {
                return quit_ ||
                       (pause_count_ == 0 && job_serial_ != last_serial);
            });
            if (quit_) {
                if (perf_.trace) std::fclose(perf_.trace);
                perf_.trace = nullptr;
                return;
            }
            if (pause_count_ > 0) {
                // Pause must be quiescent: no work in flight when the
                // caller continues.
                lock.unlock();
                for (uint32_t s = 0; s < gfx::kFramesInFlight; ++s)
                    complete_slot(s);
                lock.lock();
                continue;
            }
            idle_ = false;
            this_cycle = cycle_seq_.fetch_add(1) + 1;
            fields_changed = job_serial_ != last_serial;
            last_serial = job_serial_;
            // Adopt on snapshot identity: revision numbers restart in a
            // loaded document and can collide.
            if (job_.doc && job_.doc != doc_snap) {
                doc_snap = job_.doc;
                base_revision = job_.doc_revision;
                doc_revision = base_revision;
                local_valid = false;
                doc_changed = true;
            }
            if (job_.gesture_revision > doc_revision && doc_snap) {
                if (!local_valid) {
                    doc_local = *doc_snap;
                    local_valid = true;
                }
                if (doc::Sequence* gs =
                        doc_local.find_sequence(job_.gesture_seq))
                    if (doc::Placement* gp = doc::find_placement(
                            *gs, job_.gesture_place.id))
                        *gp = job_.gesture_place;
                doc_revision = job_.gesture_revision;
                doc_changed = true;
            }
            if (job_.analysis_stamp != analysis_stamp) {
                analysis = job_.analysis;
                has_analysis = job_.has_analysis;
                analysis_stamp = job_.analysis_stamp;
                doc_changed = true;
            }
            if (job_.node_audio != node_audio) {
                node_audio = job_.node_audio;
                doc_changed = true;
            }
            if (job_.node_camera != node_camera) {
                node_camera = job_.node_camera;
                doc_changed = true;
            }
            if (job_.pin_planes != pin_planes) {
                pin_planes = job_.pin_planes;
                engine->set_track_planes(pin_planes);
                doc_changed = true;
            }
            if (job_.bundle_stamp != bundle_stamp) {
                bundles = job_.bundles;
                bundle_stamp = job_.bundle_stamp;
                doc_changed = true;   // different media, same document
            }
            if (job_.glyph_pending) {
                job_.glyph_pending = false;
                std::vector<uint8_t> bytes = std::move(job_.glyph_data);
                const uint32_t gw = job_.glyph_w, gh = job_.glyph_h;
                const float gt = job_.glyph_tile;
                const uint32_t gc = job_.glyph_cols, gr = job_.glyph_rows;
                const bool color = job_.glyph_is_color;
                lock.unlock();
                if (color)
                    engine->set_glyph_atlas_rgba(bytes.data(), gw, gh, gt,
                                                 gc, gr, /*slot=*/2);
                else
                    engine->set_glyph_atlas(bytes.data(), gw, gh, gt, gc, gr,
                                            /*slot=*/2);
                lock.lock();
                doc_changed = true;
            }
            if (job_.scope_pending) {
                job_.scope_pending = false;
                std::vector<int16_t> mono = std::move(job_.scope_data);
                const uint32_t rate = job_.scope_rate;
                lock.unlock();
                engine->set_scope_audio(std::move(mono), rate);
                lock.lock();
                doc_changed = true;
            }
            preview_node = job_.preview_node;
            preview_layer = job_.preview_layer;
            sel_placement = job_.sel_placement;
            look_id = job_.look_id;
            preview_div = job_.preview_div;
            pub_w = job_.pub_w;
            pub_h = job_.pub_h;
            live_mode = job_.live_mode;
            app_seconds = job_.app_seconds;
            env_key_time = job_.env_key_time;
            want_source = job_.want_source;
            proxy_active = job_.proxy_active;
            interactive = job_.interactive;
            scrubbing = job_.scrubbing;
        }
        if (!doc_snap) continue;
        const doc::Document& doc = local_valid ? doc_local : *doc_snap;

        // Tick the fallback clock on every cycle, including skipped ones.
        player.tick();
        const uint32_t mod_frame = player.current_frame_index();
        if (!doc_changed && !fields_changed && !pending_render &&
            !live_mode && last_had_frame &&
            mod_frame == last_rendered_frame && !engine->ed_walk_pending()) {
            // Idle is legal only with an empty pipeline: drain first.
            for (uint32_t s = 0; s < gfx::kFramesInFlight; ++s)
                complete_slot(s);
            continue;
        }
        // A decided render stays owed until it publishes. Retry, do not stall.
        if (!pending_render)
            cycle_start = std::chrono::steady_clock::now();
        pending_render = true;

        const double mod_fps = player.fps();   // normalized > 0 by Player
        uint32_t canvas_w = 0, canvas_h = 0;
        doc::canvas_size(doc, &canvas_w, &canvas_h);

        // Render on the remapped frame. Modulation stays on the raw playhead.
        uint32_t play_frame = mod_frame;
        if (look_id == doc.root_sequence) {
            const uint32_t span =
                doc::sequence_duration(doc, doc.sequence(look_id));
            play_frame = remap.source_frame(
                doc, mod_frame, mod_fps, has_analysis ? &analysis : nullptr,
                span, live_mode ? app_seconds : -1.0);
        }

        const auto tp0 = std::chrono::steady_clock::now();
        pool.set_document(doc, look_id, bundles, doc_revision);
        // Set loop bounds only when they are in pool time, not remapped time.
        uint32_t loop_i = 0, loop_o = 0;
        if (player.looping() && player.playing() && play_frame == mod_frame)
            player.loop_bounds(&loop_i, &loop_o);
        pool.set_loop(loop_i, loop_o);
        const std::vector<media::SourceFrame>& decoded =
            pool.collect(play_frame, scrubbing);
        const auto tp1 = std::chrono::steady_clock::now();
        const auto lsrc = to_layer_sources(decoded);

        // The reference source is the first layer source frame.
        mod::SourceFrameView sfv;
        const gfx::Engine::LayerSourceFrame* ref =
            lsrc.empty() ? nullptr : &lsrc.front();
        if (ref) sfv = source_view(ref->planes);
        const doc::Document resolved = mod::resolve(
            doc, mod_frame, mod_fps, has_analysis ? &analysis : nullptr,
            live_mode ? app_seconds : -1.0, live_mode ? env_key_time : -1.0,
            &sfv, node_audio ? node_audio.get() : nullptr,
            node_camera ? node_camera.get() : nullptr);
        const auto tp2 = std::chrono::steady_clock::now();
        engine->set_preview_divisor(preview_div);
        engine->cache().set_budget(static_cast<size_t>(doc.cache_mb) << 20);

        // Recompute the doc hash leg only when the document changes.
        uint64_t cache_ctx = 0;
        // A cache hit freezes the node thumbnails, so a look skips the cache.
        const bool thumbs_visible = doc.find_look(look_id) != nullptr;
        if (!live_mode && !want_source && !interactive && !thumbs_visible &&
            doc.cache_mb > 0) {
            if (cache_hash_revision != doc_revision) {
                cache_hash_revision = doc_revision;
                const std::string doc_json =
                    json::write(doc::doc_to_json(doc), false);
                cache_doc_hash = fnv1a(doc_json.data(), doc_json.size());
                cache_doc_history = doc::document_uses_history(doc);
            }
            if (!cache_doc_history) {
                uint64_t ctx = cache_doc_hash;
                ctx = hash_combine(ctx, preview_div);
                ctx = hash_combine(ctx, preview_node);
                ctx = hash_combine(ctx, preview_layer);
                // The doc hash covers content, so the key adds only the id.
                ctx = hash_combine(ctx, look_id);
                ctx = hash_combine(ctx, has_analysis ? 1u : 0u);
                ctx = hash_combine(ctx, proxy_active ? 2u : 3u);
                ctx = hash_combine(ctx, bundle_stamp);
                cache_ctx = ctx | 1u;
            }
        }

        // Take the only GPU sync after decode and resolve, not before.
        const double g_wait = complete_slot(slot);

        // Render at working res. Publish auto-fits the display, but the
        // root sequence stays native.
        const uint32_t fw = gfx::even_down(canvas_w, preview_div);
        const uint32_t fh = gfx::even_down(canvas_h, preview_div);
        // Snap to a full, half, or quarter rung that still covers the display.
        uint32_t vdiv = 1;
        if (look_id != doc.root_sequence && pub_w && pub_h) {
            if (fw / 2 >= pub_w && fh / 2 >= pub_h) vdiv = 2;
            if (fw / 4 >= pub_w && fh / 4 >= pub_h) vdiv = 4;
        }
        const uint32_t pw = gfx::even_down(fw, vdiv);
        const uint32_t ph = gfx::even_down(fh, vdiv);
        int target = -1;
        {
            std::lock_guard<std::mutex> lock(m_);
            const uint64_t completed =
                completed_ui_frame_.load(std::memory_order_relaxed);
            for (int i = 0; i < static_cast<int>(published_.size()); ++i) {
                if (i == latest_) continue;
                bool held = false;
                for (const InFlight& fl : inflight_)
                    if (fl.pending && fl.target == i) held = true;
                if (held) continue;
                if (published_[static_cast<size_t>(i)].last_ui_frame <=
                    completed) {
                    target = i;
                    break;
                }
            }
            if (target >= 0 &&
                !ensure_published(published_[static_cast<size_t>(target)],
                                  pw, ph, want_source, completed)) {
                log_error("render: ensure_published failed %ux%u", pw, ph);
                target = -1;
            }
        }
        if (target < 0) {
            static uint32_t s_starve = 0;
            if (++s_starve % 240 == 0)
                log_error("render: publish slots starved (%u retries)",
                          s_starve);
            continue;   // the UI holds all slots, retry
        }
        Published& pub = published_[static_cast<size_t>(target)];

        vkResetFences(device.device(), 1, &fence_[slot]);
        VkCommandBufferBeginInfo begin{
            VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO};
        begin.flags = VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT;
        vkBeginCommandBuffer(cmd_[slot], &begin);

        gfx::GpuImage* source_image = nullptr;
        // Do not store to the cache while playing or scrubbing. Hits serve.
        gfx::GpuImage* final_image = engine->render(
            cmd_[slot], slot, resolved, look_id, play_frame, mod_fps, canvas_w,
            canvas_h, cache_ctx, mod_frame,
            want_source ? &source_image : nullptr,
            lsrc.empty() ? nullptr : lsrc.data(), lsrc.size(),
            preview_node, preview_layer, sel_placement,
            /*cache_store=*/!player.playing() && !scrubbing);

        bool published_ok = false;
        if (!final_image)
            log_error("render: NULL frame (look %llu frame %u)",
                      static_cast<unsigned long long>(look_id), play_frame);
        else if (final_image->width() != fw || final_image->height() != fh)
            log_error("render: size mismatch %ux%u vs %ux%u",
                      final_image->width(), final_image->height(), fw, fh);
        if (final_image && final_image->width() == fw &&
            final_image->height() == fh) {
            // Blit, not copy: the publish may downscale (viewport res).
            auto copy_into = [&](gfx::GpuImage& src, gfx::GpuImage& dst) {
                src.transition(cmd_[slot], VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL);
                dst.transition(cmd_[slot], VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL);
                VkImageBlit region{};
                region.srcSubresource = {VK_IMAGE_ASPECT_COLOR_BIT, 0, 0, 1};
                region.dstSubresource = {VK_IMAGE_ASPECT_COLOR_BIT, 0, 0, 1};
                region.srcOffsets[1] = {static_cast<int32_t>(src.width()),
                                        static_cast<int32_t>(src.height()),
                                        1};
                region.dstOffsets[1] = {static_cast<int32_t>(pw),
                                        static_cast<int32_t>(ph), 1};
                vkCmdBlitImage(cmd_[slot], src.image(),
                               VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL,
                               dst.image(),
                               VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL, 1,
                               &region, VK_FILTER_LINEAR);
                dst.transition(cmd_[slot],
                               VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL);
            };
            copy_into(*final_image, *pub.final_img);
            const bool with_source = want_source && source_image;
            if (with_source) copy_into(*source_image, *pub.source_img);
            pub.has_source = with_source;
            if (gfx::GpuImage* atlas = engine->thumb_atlas()) {
                atlas->transition(cmd_[slot],
                                  VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL);
                pub.thumb_img->transition(
                    cmd_[slot], VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL);
                VkImageCopy tregion{};
                tregion.srcSubresource = {VK_IMAGE_ASPECT_COLOR_BIT, 0, 0,
                                          1};
                tregion.dstSubresource = {VK_IMAGE_ASPECT_COLOR_BIT, 0, 0,
                                          1};
                tregion.extent = {atlas->width(), atlas->height(), 1};
                vkCmdCopyImage(cmd_[slot], atlas->image(),
                               VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL,
                               pub.thumb_img->image(),
                               VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL, 1,
                               &tregion);
                pub.thumb_img->transition(
                    cmd_[slot], VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL);
                pub.thumb_cells = engine->thumb_cells();
                pub.has_thumbs = true;
            }
            published_ok = true;
        }
        vkEndCommandBuffer(cmd_[slot]);
        const auto tp3 = std::chrono::steady_clock::now();

        VkSubmitInfo submit{VK_STRUCTURE_TYPE_SUBMIT_INFO};
        submit.commandBufferCount = 1;
        submit.pCommandBuffers = &cmd_[slot];
        {
            std::lock_guard<std::mutex> qlock(device.queue_mutex());
            if (vkQueueSubmit(device.graphics_queue(), 1, &submit,
                              fence_[slot]) != VK_SUCCESS)
                continue;
        }
        // Do not wait here. The fence retires at the next reuse of this slot.
        InFlight& fl = inflight_[slot];
        fl.pending = true;
        fl.published_ok = published_ok;
        fl.target = target;
        fl.doc_revision = doc_revision;
        fl.cycle_seq = this_cycle;
        fl.sel_placement = sel_placement;
        fl.measured = engine->measure_recorded();
        slot = (slot + 1) % gfx::kFramesInFlight;

        double phase_now[4] = {};
        {
            auto ema_ms = [&](std::atomic<uint32_t>& cell, int idx,
                              double ms) {
                phase_now[idx] = ms;
                const double prev =
                    cell.load(std::memory_order_relaxed) / 100.0;
                const double ema =
                    prev <= 0.0 ? ms : prev * 0.7 + ms * 0.3;
                cell.store(
                    static_cast<uint32_t>(std::min(ema * 100.0, 4.0e9)),
                    std::memory_order_relaxed);
            };
            auto ms_between = [](auto a, auto b) {
                return std::chrono::duration<double, std::milli>(b - a)
                    .count();
            };
            ema_ms(phase_ms_x100_[0], 0, ms_between(tp0, tp1));
            ema_ms(phase_ms_x100_[1], 1, ms_between(tp1, tp2));
            ema_ms(phase_ms_x100_[2], 2, ms_between(tp2, tp3));
            ema_ms(phase_ms_x100_[3], 3, g_wait);
        }

        if (published_ok &&
            (!last_had_frame || mod_frame != last_rendered_frame))
            frames_advanced_.fetch_add(1, std::memory_order_relaxed);
        last_rendered_frame = mod_frame;
        last_had_frame = true;
        // Force a re-collect: an approximated scrub frame must converge.
        if (pool.approximated()) last_rendered_frame = 0xFFFFFFFFu;
        {
            const double ms =
                std::chrono::duration<double, std::milli>(
                    std::chrono::steady_clock::now() - cycle_start)
                    .count();
            const double prev =
                cycle_ms_x100_.load(std::memory_order_relaxed) / 100.0;
            const double ema = prev <= 0.0 ? ms : prev * 0.7 + ms * 0.3;
            cycle_ms_x100_.store(
                static_cast<uint32_t>(std::min(ema * 100.0, 4.0e9)),
                std::memory_order_relaxed);
            perf_record(ms, phase_now);
        }
        pending_render = false;
    }
}

// This worker owns a private Engine. Do not share the preview engine.
// Fence-wait every submission inline: slot 0 arenas must not overlap.
class ThumbWorker {
public:
    struct Req {
        uint64_t key = 0;
        uint64_t entity = 0;   // doc entity id; 0 = preset payload
        uint64_t stamp = 0;
        bool operator==(const Req& o) const {
            return key == o.key && entity == o.entity && stamp == o.stamp;
        }
    };

    ThumbWorker(gfx::Device& dev, std::filesystem::path shader_dir)
        : device(dev), shader_dir_(std::move(shader_dir)) {}
    ~ThumbWorker() { stop(); }

    bool start() {
        VkCommandPoolCreateInfo pool_info{
            VK_STRUCTURE_TYPE_COMMAND_POOL_CREATE_INFO};
        pool_info.flags = VK_COMMAND_POOL_CREATE_RESET_COMMAND_BUFFER_BIT;
        pool_info.queueFamilyIndex = device.graphics_family();
        if (vkCreateCommandPool(device.device(), &pool_info, nullptr,
                                &pool_) != VK_SUCCESS)
            return false;
        VkCommandBufferAllocateInfo cb{
            VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO};
        cb.commandPool = pool_;
        cb.level = VK_COMMAND_BUFFER_LEVEL_PRIMARY;
        cb.commandBufferCount = 1;
        if (vkAllocateCommandBuffers(device.device(), &cb, &cmd_) !=
            VK_SUCCESS)
            return false;
        VkFenceCreateInfo fence_info{VK_STRUCTURE_TYPE_FENCE_CREATE_INFO};
        if (vkCreateFence(device.device(), &fence_info, nullptr, &fence_) !=
            VK_SUCCESS)
            return false;
        published_.resize(2 + gfx::kFramesInFlight);
        thread_ = std::thread([this] { run(); });
        return true;
    }

    void stop() {
        {
            std::lock_guard<std::mutex> lock(m_);
            quit_ = true;
        }
        cv_.notify_all();
        if (thread_.joinable()) thread_.join();
        device.wait_idle();
        published_.clear();
        engine_.reset();
        if (fence_) vkDestroyFence(device.device(), fence_, nullptr);
        fence_ = VK_NULL_HANDLE;
        if (pool_) vkDestroyCommandPool(device.device(), pool_, nullptr);
        pool_ = VK_NULL_HANDLE;
    }

    // Pause must be quiescent: no work in flight when the caller continues.
    void pause() {
        std::unique_lock<std::mutex> lock(m_);
        ++pause_count_;
        cv_.wait(lock, [&] { return idle_ || quit_; });
    }
    void resume() {
        {
            std::lock_guard<std::mutex> lock(m_);
            --pause_count_;
        }
        cv_.notify_all();
    }

    // Call from the UI thread once per frame. Do not copy the doc snapshot.
    void set_job(std::shared_ptr<const doc::Document> doc,
                 uint64_t revision,
                 const std::vector<media::AssetBundle>& bundles,
                 uint64_t bundle_stamp, const std::vector<Req>& reqs,
                 const std::vector<std::pair<uint64_t, doc::Preset>>&
                     presets,
                 uint64_t presets_stamp) {
        std::lock_guard<std::mutex> lock(m_);
        if (doc && doc != job_doc_) {
            job_doc_ = std::move(doc);
            job_revision_ = revision;
        }
        if (job_bundle_stamp_ != bundle_stamp) {
            job_bundles_ = bundles;
            job_bundle_stamp_ = bundle_stamp;
        }
        if (job_presets_stamp_ != presets_stamp) {
            job_presets_ = presets;
            job_presets_stamp_ = presets_stamp;
        }
        if (!(job_reqs_ == reqs)) job_reqs_ = reqs;
        cv_.notify_all();
    }

    struct View {
        gfx::GpuImage* img = nullptr;
        std::unordered_map<uint64_t, uint32_t> cells;
    };
    View acquire(uint64_t ui_frame) {
        std::lock_guard<std::mutex> lock(m_);
        if (latest_ < 0 || !published_[static_cast<size_t>(latest_)].ready)
            return {};
        Published& p = published_[static_cast<size_t>(latest_)];
        p.last_ui_frame = ui_frame;
        View v;
        v.img = p.img.get();
        v.cells = p.cells;
        return v;
    }
    void set_completed_ui_frame(uint64_t f) {
        completed_ui_frame_.store(f, std::memory_order_relaxed);
    }

    gfx::Device& device;

    std::mutex m_;
    std::condition_variable cv_;

private:
    void run();
    void render_one(const Req& req, const doc::Document& rdoc);
    void publish();
    const media::ThumbStripData* strip_for(uint64_t asset,
                                           const doc::Document& rdoc);
    void submit_and_wait(VkQueue queue) {
        {
            std::lock_guard<std::mutex> qlock(device.queue_mutex());
            VkSubmitInfo submit{VK_STRUCTURE_TYPE_SUBMIT_INFO};
            submit.commandBufferCount = 1;
            submit.pCommandBuffers = &cmd_;
            if (vkQueueSubmit(queue, 1, &submit, fence_) != VK_SUCCESS)
                return;
        }
        vkWaitForFences(device.device(), 1, &fence_, VK_TRUE, UINT64_MAX);
        vkResetFences(device.device(), 1, &fence_);
    }

    std::filesystem::path shader_dir_;
    std::unique_ptr<gfx::Engine> engine_;   // thread-created, private
    std::thread thread_;
    bool quit_ = false;
    bool idle_ = false;
    int pause_count_ = 0;
    VkCommandPool pool_ = VK_NULL_HANDLE;
    VkCommandBuffer cmd_ = VK_NULL_HANDLE;
    VkFence fence_ = VK_NULL_HANDLE;

    // Job mailbox (UI writes under m_).
    std::shared_ptr<const doc::Document> job_doc_;
    uint64_t job_revision_ = 0;
    std::vector<media::AssetBundle> job_bundles_;
    uint64_t job_bundle_stamp_ = ~0ull;
    std::vector<Req> job_reqs_;
    std::vector<std::pair<uint64_t, doc::Preset>> job_presets_;
    uint64_t job_presets_stamp_ = ~0ull;

    // Worker-side snapshots.
    std::vector<media::AssetBundle> bundles_;
    uint64_t bundle_stamp_ = ~0ull;
    std::vector<Req> reqs_;
    std::vector<std::pair<uint64_t, doc::Preset>> presets_;
    uint64_t presets_stamp_ = ~0ull;

    // Drop the strip cache when the bundles change.
    struct Slot {
        uint32_t cell = 0;
        uint64_t stamp = 0;
        uint64_t last_used = 0;
    };
    std::unordered_map<uint64_t, Slot> cells_;
    uint64_t use_counter_ = 0;
    std::unordered_map<uint64_t, media::ThumbStripData> strips_;

    // Rewrite a slot only after the UI frame that read it retires.
    struct Published {
        std::unique_ptr<gfx::GpuImage> img;
        std::unordered_map<uint64_t, uint32_t> cells;
        uint64_t last_ui_frame = 0;
        bool ready = false;
    };
    std::vector<Published> published_;
    int latest_ = -1;
    std::atomic<uint64_t> completed_ui_frame_{0};
};

void ThumbWorker::run() {
    // Build the engine on this thread. Submit on the low priority queue.
    engine_ = gfx::Engine::create(device, shader_dir_,
                                  device.thumb_queue());
    if (!engine_) {
        log_error("thumb worker: engine create failed - gallery "
                  "thumbnails stay placeholders");
        std::unique_lock<std::mutex> lock(m_);
        idle_ = true;
        cv_.notify_all();
        cv_.wait(lock, [&] { return quit_; });
        return;
    }
    std::shared_ptr<const doc::Document> doc;
    for (;;) {
        {
            std::unique_lock<std::mutex> lock(m_);
            idle_ = true;
            cv_.notify_all();
            cv_.wait_for(lock, std::chrono::milliseconds(50),
                         [&] { return quit_; });
            if (quit_) return;
            if (pause_count_ > 0) continue;   // idle_ holds while paused
            doc = job_doc_;
            if (bundle_stamp_ != job_bundle_stamp_) {
                bundles_ = job_bundles_;
                bundle_stamp_ = job_bundle_stamp_;
                strips_.clear();
            }
            if (presets_stamp_ != job_presets_stamp_) {
                presets_ = job_presets_;
                presets_stamp_ = job_presets_stamp_;
            }
            reqs_ = job_reqs_;
        }
        if (!doc) continue;
        auto next_pending = [&]() -> const Req* {
            for (const Req& r : reqs_) {
                auto it = cells_.find(r.key);
                if (it == cells_.end() || it->second.stamp != r.stamp)
                    return &r;
            }
            return nullptr;
        };
        const Req* pending = next_pending();
        if (!pending) continue;
        {
            std::lock_guard<std::mutex> lock(m_);
            idle_ = false;
        }
        for (int n = 0; pending && n < 16; ++n) {
            // Check quit between renders so stop() does not wait for
            // the full batch.
            {
                std::lock_guard<std::mutex> lock(m_);
                if (quit_) return;
            }
            render_one(*pending, *doc);
            pending = next_pending();
        }
        publish();
    }
}

const media::ThumbStripData* ThumbWorker::strip_for(
    uint64_t asset, const doc::Document& rdoc) {
    auto it = strips_.find(asset);
    if (it != strips_.end()) return it->second.count ? &it->second : nullptr;
    media::ThumbStripData strip;
    if (const doc::Asset* a = rdoc.find_asset(asset)) {
        if (!a->path.empty()) {
            const BundlePaths paths =
                resolve_bundle(u8_to_path(a->path));
            if (!paths.base.empty()) {
                std::filesystem::path tpath = paths.base;
                tpath.replace_extension(".thumbs");
                media::read_thumbs(tpath, &strip);
            }
        }
    }
    auto [ins, ok] = strips_.emplace(asset, std::move(strip));
    (void)ok;
    return ins->second.count ? &ins->second : nullptr;
}

void ThumbWorker::render_one(const Req& req, const doc::Document& rdoc) {
    constexpr uint32_t kCells =
        gfx::Engine::kGalleryCols * gfx::Engine::kGalleryRows;
    uint32_t cell = 0;
    auto have = cells_.find(req.key);
    if (have != cells_.end()) {
        cell = have->second.cell;
    } else if (cells_.size() < kCells) {
        std::vector<char> used(kCells, 0);
        for (const auto& [k, sl] : cells_) used[sl.cell] = 1;
        for (uint32_t c = 0; c < kCells; ++c)
            if (!used[c]) {
                cell = c;
                break;
            }
    } else {
        uint64_t evict = 0, oldest = ~0ull;
        for (const auto& [k, sl] : cells_) {
            bool wanted = false;
            for (const Req& r : reqs_)
                if (r.key == k) {
                    wanted = true;
                    break;
                }
            if (wanted) continue;
            if (sl.last_used < oldest) {
                oldest = sl.last_used;
                evict = k;
            }
        }
        if (!evict) return;   // request list capped at the cell count
        cell = cells_[evict].cell;
        cells_.erase(evict);
    }
    VkCommandBufferBeginInfo begin{
        VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO};
    begin.flags = VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT;
    vkBeginCommandBuffer(cmd_, &begin);
    gfx::GpuImage* timg = nullptr;
    // Plane storage must outlive render(): uploads copy at record time.
    std::vector<codec::DecodedFrame> planes;
    std::vector<gfx::Engine::LayerSourceFrame> lsrc;
    if (req.entity) {
        uint32_t cw2 = 0, ch2 = 0;
        doc::canvas_size(rdoc, &cw2, &ch2);
        const double ca =
            ch2 ? static_cast<double>(cw2) / ch2 : 16.0 / 9.0;
        uint32_t tw = 320, th2 = 180;
        if (ca >= 320.0 / 180.0)
            th2 = static_cast<uint32_t>(320.0 / std::max(ca, 0.1));
        else
            tw = static_cast<uint32_t>(180.0 * ca);
        tw = std::max(16u, tw & ~1u);
        th2 = std::max(16u, th2 & ~1u);
        const std::vector<doc::MediaInstance> flat =
            doc::flatten_media_sources(rdoc, req.entity);
        size_t nact = 0;
        for (const doc::MediaInstance& mi : flat)
            if (mi.t_in <= 0.0 && mi.t_out > 0.0) ++nact;
        planes.reserve(nact);
        for (const doc::MediaInstance& mi : flat) {
            if (!(mi.t_in <= 0.0 && mi.t_out > 0.0)) continue;
            const media::ThumbStripData* strip = strip_for(mi.asset, rdoc);
            if (!strip) continue;
            uint32_t frames = 0;
            if (const doc::Asset* a = rdoc.find_asset(mi.asset))
                frames = a->frame_count;
            uint32_t ci = 0;
            const double sf =
                std::max(0.0, doc::media_asset_frame(mi, 0.0));
            if (frames > 1 && strip->count > 1)
                ci = std::min<uint32_t>(
                    strip->count - 1,
                    static_cast<uint32_t>(sf * strip->count / frames));
            // Convert to limited-range I420. Chroma comes from the top
            // left of each 2x2 block.
            const uint32_t sw = strip->w & ~1u, sh = strip->h & ~1u;
            if (!sw || !sh) continue;
            codec::DecodedFrame df;
            df.width = sw;
            df.height = sh;
            df.y_stride = sw;
            df.uv_stride = sw / 2;
            df.y.resize(static_cast<size_t>(sw) * sh);
            df.u.resize(static_cast<size_t>(sw / 2) * (sh / 2));
            df.v.resize(static_cast<size_t>(sw / 2) * (sh / 2));
            const uint8_t* rgb = strip->rgb.data() +
                                 static_cast<size_t>(ci) * strip->w *
                                     strip->h * 3;
            for (uint32_t y = 0; y < sh; ++y)
                for (uint32_t x = 0; x < sw; ++x) {
                    const uint8_t* p =
                        rgb + (static_cast<size_t>(y) * strip->w + x) * 3;
                    uint8_t yy, cb, cr;
                    color::rgb8_to_ycbcr709(p[0], p[1], p[2], &yy, &cb,
                                            &cr);
                    df.y[static_cast<size_t>(y) * sw + x] = yy;
                    if (!(y & 1) && !(x & 1)) {
                        const size_t co =
                            static_cast<size_t>(y / 2) * (sw / 2) + x / 2;
                        df.u[co] = cb;
                        df.v[co] = cr;
                    }
                }
            planes.push_back(std::move(df));
            const codec::DecodedFrame& back = planes.back();
            gfx::Engine::LayerSourceFrame lf;
            lf.key = mi.key;
            lf.content_stamp = 0;
            lf.planes = {back.y.data(),      back.y_stride,
                         back.u.data(),      back.uv_stride,
                         back.v.data(),      back.uv_stride,
                         back.width,         back.height,
                         false};
            lsrc.push_back(lf);
        }
        const doc::Document resolved =
            mod::resolve(rdoc, 0, rdoc.fps > 0.0 ? rdoc.fps : 30.0,
                         nullptr, -1.0, -1.0, nullptr, nullptr);
        timg = engine_->render(cmd_, 0, resolved, req.entity, 0,
                               rdoc.fps > 0.0 ? rdoc.fps : 30.0, tw, th2,
                               0, 0, nullptr,
                               lsrc.empty() ? nullptr : lsrc.data(),
                               lsrc.size(), 0, 0, 0, false);
    } else {
        const doc::Preset* pp = nullptr;
        for (const auto& [k, p] : presets_)
            if (k == req.key) {
                pp = &p;
                break;
            }
        if (pp) {
            // Pin the pattern shape: the source default can change.
            doc::Document pd;
            doc::Look seed = doc::make_look(pd, "preset");
            seed.layers.push_back(
                doc::make_layer(pd, doc::LayerSourceKind::TestPattern));
            pd.looks.push_back(std::move(seed));
            doc::Look& lk = pd.looks[0];
            lk.layers[0].osc_shape = 4;   // smpte bars
            doc::Group g;
            std::vector<doc::EffectInstance> nfx;
            uint64_t g_face_in = 0;
            doc::instantiate_preset(pd, *pp, &g, &nfx, &g_face_in);
            for (doc::EffectInstance& f : nfx)
                lk.layers[0].stack.push_back(std::move(f));
            lk.layers[0].groups.push_back(std::move(g));
            const doc::Document resolved = mod::resolve(
                pd, 0, 30.0, nullptr, -1.0, -1.0, nullptr, nullptr);
            timg = engine_->render(cmd_, 0, resolved, lk.id, 0, 30.0, 320,
                                   180, 0, 0, nullptr, nullptr, 0, 0, 0,
                                   0, false);
        }
    }
    if (timg) engine_->record_gallery_tap(cmd_, 0, timg, cell);
    vkEndCommandBuffer(cmd_);
    submit_and_wait(device.thumb_queue());
    // Record the stamp on failure too, or a bad graph re-arms forever.
    cells_[req.key] = Slot{cell, req.stamp, ++use_counter_};
}

void ThumbWorker::publish() {
    gfx::GpuImage* ga = engine_->gallery_atlas();
    if (!ga) return;
    int target = -1;
    {
        std::lock_guard<std::mutex> lock(m_);
        const uint64_t completed =
            completed_ui_frame_.load(std::memory_order_relaxed);
        for (int i = 0; i < static_cast<int>(published_.size()); ++i) {
            if (i == latest_) continue;
            if (published_[static_cast<size_t>(i)].last_ui_frame <=
                completed) {
                target = i;
                break;
            }
        }
    }
    if (target < 0) return;   // the UI holds every slot, wait for a batch
    Published& p = published_[static_cast<size_t>(target)];
    if (!p.img)
        p.img = gfx::GpuImage::create(
            device, VK_FORMAT_R16G16B16A16_SFLOAT, ga->width(),
            ga->height(),
            VK_IMAGE_USAGE_SAMPLED_BIT | VK_IMAGE_USAGE_TRANSFER_DST_BIT);
    if (!p.img) return;
    // Copy on the graphics queue. The barrier makes atlas writes visible.
    VkCommandBufferBeginInfo begin{
        VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO};
    begin.flags = VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT;
    vkBeginCommandBuffer(cmd_, &begin);
    ga->transition(cmd_, VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL);
    p.img->transition(cmd_, VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL);
    VkImageCopy region{};
    region.srcSubresource = {VK_IMAGE_ASPECT_COLOR_BIT, 0, 0, 1};
    region.dstSubresource = {VK_IMAGE_ASPECT_COLOR_BIT, 0, 0, 1};
    region.extent = {ga->width(), ga->height(), 1};
    vkCmdCopyImage(cmd_, ga->image(), VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL,
                   p.img->image(), VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL, 1,
                   &region);
    p.img->transition(cmd_, VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL);
    vkEndCommandBuffer(cmd_);
    submit_and_wait(device.graphics_queue());
    std::lock_guard<std::mutex> lock(m_);
    p.cells.clear();
    for (const auto& [k, sl] : cells_) p.cells.emplace(k, sl.cell);
    p.ready = true;
    latest_ = target;
}

// Mono copy decimated to about 16 kHz. Preview and export must match.
std::vector<int16_t> load_scope_audio(const std::filesystem::path& pcm_path,
                                      uint32_t* out_rate) {
    *out_rate = 0;
    if (pcm_path.empty()) return {};
    media::PcmReader pcm;
    std::string error;
    if (!pcm.open(pcm_path, &error)) return {};
    const uint32_t ch = pcm.channels();
    const uint32_t sr = pcm.sample_rate();
    if (!ch || !sr || !pcm.frame_count()) return {};
    const uint32_t decim = std::max(1u, sr / 16000u);
    std::vector<int16_t> mono;
    mono.reserve(static_cast<size_t>(pcm.frame_count() / decim) + 1);
    // Chunk size a multiple of decim so blocks never straddle chunks.
    const size_t chunk = static_cast<size_t>(65536 - (65536 % decim));
    std::vector<int16_t> buf(chunk * ch);
    uint64_t pos = 0;
    while (pos < pcm.frame_count()) {
        const size_t got = pcm.read(pos, buf.data(), chunk);
        if (!got) break;
        for (size_t b = 0; b + decim <= got; b += decim) {
            int32_t acc = 0;
            for (size_t f = 0; f < decim; ++f)
                for (uint32_t c = 0; c < ch; ++c)
                    acc += buf[(b + f) * ch + c];
            mono.push_back(static_cast<int16_t>(
                acc / static_cast<int32_t>(decim * ch)));
        }
        pos += got;
    }
    *out_rate = sr / decim;
    return mono;
}

// Decimate the project mix to a mono strip. Capped at one hour.
std::vector<int16_t> scope_audio_from_mix(const media::MixState& mix,
                                          uint32_t* out_rate,
                                          const std::atomic<bool>* cancel =
                                              nullptr) {
    *out_rate = 0;
    if (mix.root < 0 || !mix.rate || !mix.channels || mix.fps <= 0.0)
        return {};
    double end_frames = 0.0;
    for (const media::MixNode& n : mix.nodes) {
        double end = n.windowed && n.w1 < media::kMixUnbounded
                         ? n.w1
                         : 0.0;
        if (n.pcm && n.pcm->rate && n.a > 1e-9) {
            const double lf = n.local_fps > 0.0 ? n.local_fps : mix.fps;
            const double media_local =
                static_cast<double>(n.pcm->frames()) / n.pcm->rate * lf;
            end = std::max(end, (media_local - n.b) / n.a);
        }
        end_frames = std::max(end_frames, end);
    }
    if (end_frames <= 0.0) return {};
    const uint64_t total = std::min<uint64_t>(
        static_cast<uint64_t>(end_frames / mix.fps * mix.rate),
        3600ull * mix.rate);
    const uint32_t decim = std::max(1u, mix.rate / 16000u);
    std::vector<int16_t> mono;
    mono.reserve(total / decim + 1);
    const uint32_t chunk = 65536 - (65536 % decim);
    std::vector<int16_t> buf(static_cast<size_t>(chunk) * mix.channels);
    std::vector<float> scratch;
    for (uint64_t pos = 0; pos < total; pos += chunk) {
        if (cancel && cancel->load()) {
            *out_rate = 0;
            return {};
        }
        const uint32_t n =
            static_cast<uint32_t>(std::min<uint64_t>(chunk, total - pos));
        media::render_mix(mix, static_cast<int64_t>(pos), buf.data(), n,
                          scratch);
        for (uint32_t b = 0; b + decim <= n; b += decim) {
            int32_t acc = 0;
            for (uint32_t f = 0; f < decim; ++f)
                for (uint32_t c = 0; c < mix.channels; ++c)
                    acc += buf[(static_cast<size_t>(b) + f) * mix.channels +
                               c];
            mono.push_back(static_cast<int16_t>(
                acc / static_cast<int32_t>(decim * mix.channels)));
        }
    }
    *out_rate = mix.rate / decim;
    return mono;
}

// Runs on its own thread with a private Engine. Queue submits use the mutex.
std::unique_ptr<ExportJob> start_export(
    gfx::Device& device, const std::filesystem::path& shader_dir,
    const std::vector<media::AssetBundle>& bundles, const PcmCache& pcm,
    const std::filesystem::path& scope_pcm, const doc::Document& doc,
    uint64_t export_look_id, const mod::AnalysisCurves* analysis,
    std::shared_ptr<const mod::NodeAudioMap> node_audio,
    std::shared_ptr<const mod::NodeCameraMap> node_camera,
    std::shared_ptr<const gfx::Engine::PinPlaneMap> pin_planes,
    const std::filesystem::path& out_path) {
    auto job = std::make_unique<ExportJob>();
    job->out_path = out_path;
    ExportJob* raw = job.get();
    doc::Document doc_copy = doc;
    mod::AnalysisCurves curves_copy;
    const bool has_analysis = analysis != nullptr;
    if (analysis) curves_copy = *analysis;
    std::vector<media::AssetBundle> bundle_copy = bundles;
    PcmCache pcm_copy = pcm;   // shared buffers, not a second load
    job->thread = std::thread([&device, shader_dir, scope_pcm,
                               bundle_copy = std::move(bundle_copy),
                               pcm_copy = std::move(pcm_copy),
                               doc_copy = std::move(doc_copy),
                               curves_copy = std::move(curves_copy),
                               node_audio = std::move(node_audio),
                               node_camera = std::move(node_camera),
                               pin_planes = std::move(pin_planes),
                               has_analysis, raw, out_path,
                               export_look_id] {
        auto engine = gfx::Engine::create(device, shader_dir);
        auto readback = gfx::Nv12Readback::create(device, shader_dir);
        if (!engine || !readback) {
            raw->result.error = "export renderer init failed";
            raw->done = true;
            return;
        }
        // Export uses the same divisor as preview: kernels sample by uv.
        engine->set_track_planes(pin_planes);
        engine->set_preview_divisor(doc_copy.export_scale);
        uint32_t canvas_w = 0, canvas_h = 0;
        doc::canvas_size(doc_copy, &canvas_w, &canvas_h);
        const uint32_t out_w =
            gfx::even_down(canvas_w, doc_copy.export_scale);
        const uint32_t out_h =
            gfx::even_down(canvas_h, doc_copy.export_scale);
        // MezReaders are single-thread objects, so this pool must be private.
        media::DecodePool pool("export");
        pool.set_document(doc_copy, export_look_id, bundle_copy, 1);
        mod::TimeRemap remap;
        double fps = project_fps(doc_copy, bundle_copy);
        if (const doc::Look* fl = doc_copy.find_look(export_look_id)) {
            if (doc::format_has_fps(fl->format)) fps = fl->format.fps;
        } else if (const doc::Sequence* fs =
                       doc_copy.find_sequence(export_look_id)) {
            if (doc::format_has_fps(fs->format)) fps = fs->format.fps;
        }
        auto mix = std::make_shared<media::MixState>(
            build_mix(doc_copy, export_look_id, pcm_copy, fps,
                      media::Player::kClockRate, media::Player::kChannels));
        {
            uint32_t scope_rate = 0;
            std::vector<int16_t> scope_mono =
                scope_pcm.empty()
                    ? scope_audio_from_mix(*mix, &scope_rate)
                    : load_scope_audio(scope_pcm, &scope_rate);
            engine->set_scope_audio(std::move(scope_mono), scope_rate);
        }
        // Do not use the fallback accessor: it gives root trim for a look.
        uint32_t total = 0, t_in = 0, t_out = 0;
        if (const doc::Look* el = doc_copy.find_look(export_look_id)) {
            total = doc::look_duration(doc_copy, *el);
            t_out = total;
        } else if (const doc::Sequence* es =
                       doc_copy.find_sequence(export_look_id)) {
            total = doc::sequence_duration(doc_copy, *es);
            t_in = total ? std::min(es->trim_in, total - 1) : 0;
            t_out = es->trim_out ? std::min(es->trim_out, total) : total;
        }
        if (total == 0) {
            raw->result.error = "nothing to export (empty entity)";
            raw->done = true;
            return;
        }
        const uint32_t span = t_out > t_in ? t_out - t_in : total;
        auto producer = [&](uint32_t f, std::vector<uint8_t>& nv12) {
            const uint32_t abs_f = t_in + f;
            // Export walks frames in order, so the prefix sum is incremental.
            uint32_t play_frame = abs_f;
            if (export_look_id == doc_copy.root_sequence)
                play_frame = remap.source_frame(
                    doc_copy, abs_f, fps,
                    has_analysis ? &curves_copy : nullptr, total);
            const std::vector<media::SourceFrame>& decoded =
                pool.collect(play_frame);
            const auto lsrc = to_layer_sources(decoded);
            mod::SourceFrameView sfv;
            if (!lsrc.empty()) sfv = source_view(lsrc.front().planes);
            const doc::Document resolved = mod::resolve(
                doc_copy, abs_f, fps, has_analysis ? &curves_copy : nullptr,
                -1.0, -1.0, &sfv,
                node_audio ? node_audio.get() : nullptr,
                node_camera ? node_camera.get() : nullptr);
            return readback->render(*engine, resolved, export_look_id,
                                    play_frame, fps, canvas_w, canvas_h, nv12,
                                    0, abs_f,
                                    lsrc.empty() ? nullptr : lsrc.data(),
                                    lsrc.size());
        };
        media::ExportOptions options;
        options.video_bitrate_bps = static_cast<uint32_t>(
            std::clamp(doc_copy.export_bitrate_mbps, 1.0f, 60.0f) *
            1'000'000.0f);
        // A positive audio_offset_ms moves audio later, so subtract it.
        options.audio_skip_samples =
            media::frame_to_sample(t_in, fps, media::Player::kClockRate) -
            media::seconds_to_samples(
                static_cast<double>(doc_copy.audio_offset_ms) * 0.001,
                media::Player::kClockRate);
        media::ExportAudio audio;
        if (doc_copy.export_audio && mix->root >= 0) {
            audio.channels = mix->channels;
            audio.rate = mix->rate;
            auto scratch = std::make_shared<std::vector<float>>();
            audio.fill = [mix, scratch](int64_t first, int16_t* out,
                                        uint32_t frames) {
                media::render_mix(*mix, first, out, frames, *scratch);
            };
        }
        uint32_t fps_num = 0, fps_den = 0;
        frame_rate_ratio(fps, bundle_copy, &fps_num, &fps_den);
        raw->result =
            media::export_movie(out_w, out_h, fps_num, fps_den, span,
                                producer, audio, out_path, options,
                                &raw->progress);
        // Abort the pool: the destructor must not wait for prewarm rolls.
        pool.abort();
        raw->done = true;
    });
    return job;
}

